package com.oms.channel.platform;

import com.ruoyi.common.core.constant.SecurityConstants;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import java.time.*;
import java.util.*;
import static com.oms.channel.platform.PlatformInteractionLog.*;
import static com.oms.channel.platform.ChannelPlatformService.map;

/** Indexed, tenant-scoped read model. Payloads and remote business progress are separate reads. */
@Service public class PlatformLogQuery {
    @Resource PlatformInteractionLog logs;
    @Resource PlatformLogBusinessClient business;
    private static final String RESULT="CASE WHEN l.result='RUNNING' AND l.create_time<DATE_SUB(NOW(),INTERVAL 90 SECOND) THEN 'UNKNOWN' ELSE l.result END";
    private static final String SELECT="l.id,l.channel_id,c.channel_name,l.app_id,l.platform_code,l.entry_kind,l.category,l.environment,l.direction,l.request_id,l.root_request_id,l.parent_request_id,l.operation_id,l.interface_name,l.action,l.source_service,l.trigger_source,l.operator,l.http_status,l.request_sent,l.platform_request_id,l.error_code,l.duration_ms,l.create_time,l.finished_at,"+RESULT+" result";
    private static final class Filter {String where=" WHERE l.company_code=? AND l.record_version=1";List<Object> args=new ArrayList<>();Filter(String company){args.add(company);}void add(String sql,Object... values){where+=sql;args.addAll(Arrays.asList(values));}}
    private <T> T data(R<T> result){require(result!=null&&R.isSuccess(result),"关联业务服务暂不可用，请稍后重试");return result.getData();}
    @SuppressWarnings("unchecked") private Filter filter(String company,Map<String,String> input){
        Filter f=new Filter(company);String number=input.getOrDefault("number","").trim(),type=input.getOrDefault("numberType","AUTO"),request=input.getOrDefault("requestId","").trim();require(number.length()<=128&&request.length()<=64,"查询编号过长");
        List<Map<String,Object>> refs=new ArrayList<>();if(!number.isEmpty()){require(("AUTO".equals(type)||NUMBER_TYPES.contains(type))&&number.matches("[A-Za-z0-9_:.\\-]{1,128}"),"单号类型或单号无效");if("AUTO".equals(type)){for(String candidate:NUMBER_TYPES)refs.add(map("type",candidate,"number",number));}else refs.add(map("type",type,"number",number));if(Arrays.asList("AUTO","OMS_ORDER","EXCHANGE","SHIPMENT","PLATFORM_TID","PLATFORM_OID","PLATFORM_EXCHANGE").contains(type)){List<Map<String,Object>> resolved=data(business.resolve(company,map("type",type,"number",number),SecurityConstants.INNER));require(resolved!=null&&resolved.size()<=300,"关联单据过多，请使用发货单或换货单号查询");for(Map<String,Object> ref:resolved){require(NUMBER_TYPES.contains(s(ref,"type"))&&s(ref,"number").matches("[A-Za-z0-9_:.\\-]{1,128}"),"业务单号无效");if(!refs.contains(ref))refs.add(ref);}}StringJoiner terms=new StringJoiner(" OR ");for(Map<String,Object> ref:refs){terms.add("(b.number_type=? AND b.number_value=?)");f.args.add(s(ref,"type"));f.args.add(s(ref,"number"));}f.where+=" AND EXISTS(SELECT 1 FROM channel_interaction_business_link b WHERE b.company_code=l.company_code AND b.log_id=l.id AND ("+terms+"))";}
        if(!request.isEmpty()){require(request.matches("[A-Za-z0-9_-]{1,64}"),"请求编号无效");f.add(" AND (l.request_id=? OR l.root_request_id=? OR l.operation_id=?)",request,request,request);}
        boolean all="true".equals(input.get("allTime"));require(!all||!number.isEmpty()||!request.isEmpty(),"本单全部时间需要精确单号或请求编号");LocalDateTime end=LocalDateTime.now().withNano(0).plusSeconds(1),start=end.minusHours(24);try{if(!all){if(!input.getOrDefault("start","").isEmpty())start=LocalDateTime.parse(input.get("start"),TIME);if(!input.getOrDefault("end","").isEmpty())end=LocalDateTime.parse(input.get("end"),TIME);require(start.isBefore(end)&&!end.isAfter(LocalDateTime.now().plusMinutes(1))&&Duration.between(start,end).compareTo(Duration.ofDays(31))<=0,"查询时间范围应在过去且不超过31天");}else start=end.minusDays(Math.max(1,Math.min(logs.summaryDays(company),3650)));}catch(java.time.format.DateTimeParseException e){throw new IllegalArgumentException("查询时间格式无效");}f.add(" AND l.create_time>=? AND l.create_time<?",start,end);
        for(String[] spec:new String[][]{{"category","AUTH,SERVICE,ORDER,SHIPPING,STOCK,PRODUCT,EXCHANGE,REFUND,NOTIFICATION,CONFIG,DATA_SYNC"},{"entryKind","OPERATION,API,SIMULATION,CONFIG,NOTIFICATION,DATA_SYNC"},{"environment","REAL,SIMULATION,LOCAL"},{"result","SUCCESS,FAILED,UNKNOWN,RUNNING"},{"triggerSource","USER,BUSINESS,SCHEDULER,SYSTEM"}}){String value=input.getOrDefault(spec[0],"");if(!value.isEmpty()){require(Arrays.asList(spec[1].split(",")).contains(value),"日志筛选值无效");String column=spec[0].equals("entryKind")?"l.entry_kind":spec[0].equals("triggerSource")?"l.trigger_source":spec[0].equals("result")?"("+RESULT+")":"l."+spec[0];f.add(" AND "+column+"=?",value);}}
        for(String[] spec:new String[][]{{"itemId","PLATFORM_ITEM"},{"skuId","PLATFORM_SKU"}}){String value=input.getOrDefault(spec[0],"");if(!value.isEmpty()){require(value.matches("[0-9]{1,19}")&&!input.getOrDefault("channelId","").isEmpty(),"商品日志查询需要店铺和有效商品编号");f.add(" AND EXISTS(SELECT 1 FROM channel_interaction_business_link b WHERE b.company_code=l.company_code AND b.log_id=l.id AND b.number_type=? AND b.number_value=?)",spec[1],value);}}
        String channel=input.getOrDefault("channelId","");if(!channel.isEmpty()){require(channel.matches("[1-9][0-9]{0,18}"),"店铺编号无效");f.add(" AND l.channel_id=?",Long.parseLong(channel));}String method=input.getOrDefault("method","").trim();if(!method.isEmpty()){require(method.matches("[A-Za-z0-9_.-]{1,128}"),"接口名称无效");f.add(" AND l.interface_name=?",method);}return f;
    }
    public Map<String,Object> list(String company,Map<String,String> input){Filter f=filter(company,input);String cursor=input.getOrDefault("cursor","");if(!cursor.isEmpty()){String[] values=cursor.split("\\|",-1);require(values.length==2&&values[1].matches("[1-9][0-9]{0,18}"),"分页游标无效");LocalDateTime time;try{time=LocalDateTime.parse(values[0],TIME);}catch(Exception e){throw new IllegalArgumentException("分页游标无效");}f.add(" AND (l.create_time<? OR (l.create_time=? AND l.id<?))",time,time,Long.parseLong(values[1]));}int limit=50;try{limit=Integer.parseInt(input.getOrDefault("limit","50"));}catch(Exception e){throw new IllegalArgumentException("分页数量无效");}require(limit>=1&&limit<=100,"每页数量应为1至100");f.args.add(limit+1);List<Map<String,Object>> rows=logs.db.queryForList("SELECT "+SELECT+" FROM channel_interaction_log l LEFT JOIN t_channel c ON UPPER(c.company_code)=UPPER(l.company_code) AND c.channel_id=l.channel_id"+f.where+" ORDER BY l.create_time DESC,l.id DESC LIMIT ?",f.args.toArray());boolean more=rows.size()>limit;if(more)rows.remove(rows.size()-1);refs(company,rows);dates(rows);String next=more?s(rows.get(rows.size()-1),"create_time")+"|"+rows.get(rows.size()-1).get("id"):"";return map("rows",rows,"has_more",more,"next_cursor",next);}
    public Map<String,Object> summary(String company,Map<String,String> input){Filter f=filter(company,input);Map<String,Object> counts=map("SUCCESS",0,"FAILED",0,"UNKNOWN",0,"RUNNING",0);for(Map<String,Object> row:logs.db.queryForList("SELECT "+RESULT+" result,COUNT(*) qty FROM channel_interaction_log l"+f.where+" GROUP BY "+RESULT,f.args.toArray()))counts.put(s(row,"result"),row.get("qty"));return counts;}
    public Map<String,Object> options(String company){return map("shops",logs.db.queryForList("SELECT channel_id,channel_name,enabled FROM t_channel WHERE UPPER(company_code)=UPPER(?) ORDER BY enabled DESC,channel_id DESC LIMIT 1000",company),"payload_days",Math.max(1,Math.min(logs.payloadDays(company),logs.summaryDays(company))),"summary_days",Math.max(1,logs.summaryDays(company)));}
    public Map<String,Object> detail(String company,long id){List<Map<String,Object>> rows=logs.db.queryForList("SELECT "+SELECT+",l.request_summary,l.response_summary FROM channel_interaction_log l LEFT JOIN t_channel c ON UPPER(c.company_code)=UPPER(l.company_code) AND c.channel_id=l.channel_id WHERE l.company_code=? AND l.id=? AND l.record_version=1",company,id);require(rows.size()==1,"日志不存在或无权访问");refs(company,rows);Map<String,Object> row=rows.get(0);List<Map<String,Object>> chain=logs.db.queryForList("SELECT "+SELECT+" FROM channel_interaction_log l LEFT JOIN t_channel c ON UPPER(c.company_code)=UPPER(l.company_code) AND c.channel_id=l.channel_id WHERE l.company_code=? AND l.record_version=1 AND (l.root_request_id=? OR (?<>'' AND l.operation_id=?)) ORDER BY l.id DESC LIMIT 101",company,row.get("root_request_id"),row.get("operation_id"),row.get("operation_id"));boolean clipped=chain.size()>100;if(clipped)chain.remove(100);if(chain.stream().noneMatch(entry->n(entry,"id")==id)){if(chain.size()==100)chain.remove(chain.size()-1);Map<String,Object> selected=new LinkedHashMap<>(row);selected.remove("refs");chain.add(selected);}chain.sort(Comparator.comparingLong(entry->n(entry,"id")));dates(chain);dates(rows);row.put("chain",chain);row.put("chain_truncated",clipped);return row;}
    public Map<String,Object> payload(String company,long id){require(logs.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE company_code=? AND id=? AND record_version=1",Integer.class,company,id)==1,"日志不存在或无权访问");List<Map<String,Object>> rows=logs.db.queryForList("SELECT request_json,response_json,request_truncated,response_truncated FROM channel_interaction_payload WHERE company_code=? AND log_id=? AND create_time>=DATE_SUB(NOW(),INTERVAL ? DAY)",company,id,Math.max(1,Math.min(logs.payloadDays(company),logs.summaryDays(company))));return rows.isEmpty()?map("expired",true,"message","脱敏报文已过保存期限；摘要与业务处理记录仍可查询"):rows.get(0);}
    private void refs(String company,List<Map<String,Object>> rows){if(rows.isEmpty())return;List<Object> args=new ArrayList<>();args.add(company);for(Map<String,Object> row:rows)args.add(row.get("id"));List<Map<String,Object>> refs=logs.db.queryForList("SELECT log_id,number_type,number_value FROM channel_interaction_business_link WHERE company_code=? AND log_id IN ("+String.join(",",Collections.nCopies(rows.size(),"?"))+") ORDER BY log_id,number_type,number_value",args.toArray());for(Map<String,Object> row:rows){List<Map<String,Object>> own=new ArrayList<>();for(Map<String,Object> ref:refs)if(n(ref,"log_id")==n(row,"id"))own.add(map("type",ref.get("number_type"),"number",ref.get("number_value")));row.put("refs",own);}}
    public Map<String,Object> context(String company,Map<String,String> input){
        String number=input.getOrDefault("number", "").trim(),type=input.getOrDefault("numberType","AUTO");
        require(number.matches("[A-Za-z0-9_:.\\-]{1,128}")&&("AUTO".equals(type)||NUMBER_TYPES.contains(type)),"业务单号无效");
        try{
            List<Map<String,Object>> refs=data(business.resolve(company,map("type",type,"number",number),SecurityConstants.INNER));
            require(refs!=null&&refs.size()<=300,"关联单据过多，请使用换货单号查询");
            List<Map<String,Object>> cases=new ArrayList<>();Set<String> seen=new HashSet<>();
            for(Map<String,Object> ref:refs)if("EXCHANGE".equals(s(ref,"type"))&&seen.add(s(ref,"number")))cases.add(ref);
            boolean clipped=cases.size()>20;if(clipped)cases=new ArrayList<>(cases.subList(0,20));
            Map<String,Object> status=states(company,cases);status.put("truncated",clipped);return status;
        }catch(RuntimeException e){return map("available",false,"rows",Collections.emptyList(),"message","该单平台处理说明暂未加载成功；可继续查看接口日志");}
    }
    public Map<String,Object> states(String company,List<Map<String,Object>> refs){require(refs!=null&&refs.size()<=100,"单次业务进度查询最多100个单号");for(Map<String,Object> ref:refs)require(NUMBER_TYPES.contains(s(ref,"type"))&&s(ref,"number").matches("[A-Za-z0-9_:.\\-]{1,128}"),"业务单号无效");try{return map("available",true,"rows",data(business.states(company,refs,SecurityConstants.INNER)),"observed_at",LocalDateTime.now().format(TIME));}catch(RuntimeException e){return map("available",false,"rows",Collections.emptyList(),"message","当前业务进度暂未查询成功；本次接口记录不受影响");}}
    private void dates(List<Map<String,Object>> rows){for(Map<String,Object> row:rows)row.replaceAll((k,v)->v instanceof LocalDateTime?((LocalDateTime)v).format(TIME):v instanceof java.sql.Timestamp?((java.sql.Timestamp)v).toLocalDateTime().format(TIME):v);}
}
